export default JSON.parse(
  "{\n  \"workId\": \"han-fei-zi\",\n  \"chapter\": {\n    \"id\": \"han-fei-zi_ch-49\",\n    \"workId\": \"han-fei-zi\",\n    \"order\": 49,\n    \"title\": \"五蠹\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 16,\n    \"passageIds\": [\n      \"han-fei-zi_ch-49_p-1\",\n      \"han-fei-zi_ch-49_p-2\",\n      \"han-fei-zi_ch-49_p-3\",\n      \"han-fei-zi_ch-49_p-4\",\n      \"han-fei-zi_ch-49_p-5\",\n      \"han-fei-zi_ch-49_p-6\",\n      \"han-fei-zi_ch-49_p-7\",\n      \"han-fei-zi_ch-49_p-8\",\n      \"han-fei-zi_ch-49_p-9\",\n      \"han-fei-zi_ch-49_p-10\",\n      \"han-fei-zi_ch-49_p-11\",\n      \"han-fei-zi_ch-49_p-12\",\n      \"han-fei-zi_ch-49_p-13\"\n    ],\n    \"tags\": [\n      \"法家\",\n      \"帝王術\",\n      \"法術勢\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 1,\n      \"canonicalText\": \"上古之世，人民少而禽獸眾，人民不勝禽獸蟲蛇，有聖人作，搆木為巢以避羣害，而民悅之，使王天下，號曰有巢氏。民食果蓏蚌蛤，腥臊惡臭而傷害腹胃，民多疾病，有聖人作，鑽燧取火以化腥臊，而民說之，使王天下，號之曰燧人氏。中古之世，天下大水，而鯀、禹決瀆。近古之世，桀、紂暴亂，而湯、武征伐。今有搆木鑽燧於夏后氏之世者，必為鯀、禹笑矣。有決瀆於殷、周之世者，必為湯、武笑矣。然則今有美堯、舜、湯、武、禹之道於當今之世者，必為新聖笑矣。是以聖人不期脩古，不法常可，論世之事，因為之備。宋人有耕田者，田中有株，兔走，觸株折頸而死，因釋其耒而守株，冀復得兔，兔不可復得，而身為宋國笑。今欲以先王之政，治當世之民，皆守株之類也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-1_s-1\",\n        \"han-fei-zi_ch-49_p-1_s-2\",\n        \"han-fei-zi_ch-49_p-1_s-3\",\n        \"han-fei-zi_ch-49_p-1_s-4\",\n        \"han-fei-zi_ch-49_p-1_s-5\",\n        \"han-fei-zi_ch-49_p-1_s-6\",\n        \"han-fei-zi_ch-49_p-1_s-7\",\n        \"han-fei-zi_ch-49_p-1_s-8\",\n        \"han-fei-zi_ch-49_p-1_s-9\",\n        \"han-fei-zi_ch-49_p-1_s-10\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"上古的世，人民少而且禽獸眾，人民不勝禽獸蟲蛇，有聖人作，搆木為巢以避羣害，而且民悅的，使王天下，號說道：有巢氏。民食果蓏蚌蛤，腥臊惡臭而且傷害腹胃，民多疾病，有聖人作，鑽燧取火以化腥臊，而且民說的，使王天下，號的說道：燧人氏。中古的世，天下大水，而且鯀、禹決瀆。近古的世，桀、紂暴亂，而且湯、武征伐。今有搆木鑽燧於夏后氏的世的人或事，必為鯀、禹笑矣。有決瀆於殷、周的世的人或事，必為湯、武笑矣。然則今有美堯、舜、湯、武、禹的道於當今的世的人或事，必為新聖笑矣。是以聖人不期脩古，不法規法令常可，論世的事，因為的備。宋人有耕田的人或事，田中有株，兔走，觸株折頸而且死，因釋他的耒而且守株，冀復得兔，兔不可復得，而且身為宋國笑。今欲以先王的政，治當世的民，皆守株的類啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「上古之世，人民少而禽獸眾，人民不勝禽獸蟲蛇，有聖人作，搆木為巢以避羣害，而民悅之，使王天下，號曰有巢氏」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「上」、「古」、「世」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「上古之世人民少而禽獸眾人民不勝禽獸蟲蛇有聖人作搆」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「民食果蓏蚌蛤，腥臊惡臭而傷害腹胃，民多疾病，有聖人作，鑽燧取火以化腥臊，而民說之，使王天下，號之曰燧人氏」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-2\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 2,\n      \"canonicalText\": \"古者丈夫不耕，草木之實足食也；婦人不織，禽獸之皮足衣也。不事力而養足，人民少而財有餘，故民不爭。是以厚賞不行，重罰不用而民自治。今人有五子不為多，子又有五子，大父未死而有二十五孫，是以人民眾而貨財寡，事力勞而供養薄，故民爭，雖倍賞累罰而不免於亂。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-2_s-1\",\n        \"han-fei-zi_ch-49_p-2_s-2\",\n        \"han-fei-zi_ch-49_p-2_s-3\",\n        \"han-fei-zi_ch-49_p-2_s-4\",\n        \"han-fei-zi_ch-49_p-2_s-5\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"古的人或事丈夫不耕，草木的實足食啊；婦人不織，禽獸的皮足衣啊。不事力而且養足，人民少而且財有餘，所以民不爭。是以厚賞賜不行，重刑罰不用而且民自治。今人有五子不為多，子又有五子，大父未死而且有二十五孫，是以人民眾而且貨財寡，事力勞而且供養薄，所以民爭，雖倍賞賜累刑罰而且不免於亂。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「古者丈夫不耕，草木之實足食也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「古」、「丈」、「不」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「古者丈夫不耕草木之實足食也婦人不織禽獸之皮足衣也」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「婦人不織，禽獸之皮足衣也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 3,\n      \"canonicalText\": \"堯之王天下也，茅茨不翦，采椽不斲，糲粢之食，藜藿之羹，冬日麑裘，夏日葛衣，雖監門之服養，不虧於此矣。禹之王天下也，身執耒臿以為民先，股無胈，脛不生毛，雖臣虜之勞不苦於此矣。以是言之，夫古之讓天子者，是去監門之養而離臣虜之勞也，古傳天下而不足多也。今之縣令，一日身死，子孫累世絜駕，故人重之；是以人之於讓也，輕辭古之天子，難去今之縣令者，薄厚之實異也。夫山居而谷汲者，膢臘而相遺以水；澤居苦水者，買庸而決竇。故饑歲之春，幼弟不饟；穰歲之秋，疏客必食；非疏骨肉愛過客也，多少之實異也。是以古之易財，非仁也，財多也；今之爭奪，非鄙也，財寡也；輕辭天子，非高也，勢薄也；爭土橐，非下也，權重也。故聖人議多少、論薄厚為之政，故罰薄不為慈，誅嚴不為戾，稱俗而行也。故事因於世，而備適於事。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-3_s-1\",\n        \"han-fei-zi_ch-49_p-3_s-2\",\n        \"han-fei-zi_ch-49_p-3_s-3\",\n        \"han-fei-zi_ch-49_p-3_s-4\",\n        \"han-fei-zi_ch-49_p-3_s-5\",\n        \"han-fei-zi_ch-49_p-3_s-6\",\n        \"han-fei-zi_ch-49_p-3_s-7\",\n        \"han-fei-zi_ch-49_p-3_s-8\",\n        \"han-fei-zi_ch-49_p-3_s-9\",\n        \"han-fei-zi_ch-49_p-3_s-10\",\n        \"han-fei-zi_ch-49_p-3_s-11\",\n        \"han-fei-zi_ch-49_p-3_s-12\",\n        \"han-fei-zi_ch-49_p-3_s-13\",\n        \"han-fei-zi_ch-49_p-3_s-14\",\n        \"han-fei-zi_ch-49_p-3_s-15\",\n        \"han-fei-zi_ch-49_p-3_s-16\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"堯的王天下啊，茅茨不翦，采椽不斲，糲粢的食，藜藿的羹，冬日麑裘，夏日葛衣，雖監門的服養，不虧於此矣。禹的王天下啊，身執耒臿以為民先，股無胈，脛不生毛，雖臣屬虜的勞不苦於此矣。以是言的，夫古的讓天子的人或事，是去監門的養而且離臣屬虜的勞啊，古傳天下而且不足多啊。今的縣令，一日身死，子孫累世絜駕，所以人重的；是以人的於讓啊，輕辭古的天子，難去今的縣令的人或事，薄厚的實異啊。夫山居而且谷汲的人或事，膢臘而且相遺以水；澤居苦水的人或事，買庸而且決竇。所以饑歲的春，幼弟不饟；穰歲的秋，疏客必食；絕不是疏骨肉愛過客啊，多少的實異啊。是以古的易財，絕不是仁啊，財多啊；今的爭奪，絕不是鄙啊，財寡啊；輕辭天子，絕不是高啊，權位威勢薄啊；爭土橐，絕不是下啊，權重啊。所以聖人議多少、論薄厚為的政，所以刑罰薄不為慈，誅嚴不為戾，稱俗而且行啊。所以事因於世，而且備適於事。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「堯之王天下也，茅茨不翦，采椽不斲，糲粢之食，藜藿之羹，冬日麑裘，夏日葛衣，雖監門之服養，不虧於此矣」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「堯」、「王」、「天」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「堯之王天下也茅茨不翦采椽不斲糲粢之食藜藿之羹冬日」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「禹之王天下也，身執耒臿以為民先，股無胈，脛不生毛，雖臣虜之勞不苦於此矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 4,\n      \"canonicalText\": \"古者文王處豐、鎬之間，地方百里，行仁義而懷西戎，遂王天下。徐偃王處漢東，地方五百里，行仁義，割地而朝者三十有六國，荊文王恐其害己也，舉兵伐徐，遂滅之。故文王行仁義而王天下，偃王行仁義而喪其國，是仁義用於古不用於今也。故曰：世異則事異。當舜之時，有苗不服，禹將伐之，舜曰：「不可。上德不厚而行武，非道也。」乃修教三年，執干戚舞，有苗乃服。共工之戰，鐵銛矩者及乎敵，鎧甲不堅者傷乎體，是干戚用於古不用於今也。故曰：事異則備變。上古競於道德，中世逐於智謀，當今爭於氣力。齊將攻魯，魯使子貢說之，齊人曰：「子言非不辯也，吾所欲者土地也，非斯言所謂也。」遂舉兵伐魯，去門十里以為界。故偃王仁義而徐亡，子貢辯智而魯削。以是言之，夫仁義辯智，非所以持國也。去偃王之仁，息子貢之智，循徐、魯之力使敵萬乘，則齊、荊之慾不得行於二國矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-4_s-1\",\n        \"han-fei-zi_ch-49_p-4_s-2\",\n        \"han-fei-zi_ch-49_p-4_s-3\",\n        \"han-fei-zi_ch-49_p-4_s-4\",\n        \"han-fei-zi_ch-49_p-4_s-5\",\n        \"han-fei-zi_ch-49_p-4_s-6\",\n        \"han-fei-zi_ch-49_p-4_s-7\",\n        \"han-fei-zi_ch-49_p-4_s-8\",\n        \"han-fei-zi_ch-49_p-4_s-9\",\n        \"han-fei-zi_ch-49_p-4_s-10\",\n        \"han-fei-zi_ch-49_p-4_s-11\",\n        \"han-fei-zi_ch-49_p-4_s-12\",\n        \"han-fei-zi_ch-49_p-4_s-13\",\n        \"han-fei-zi_ch-49_p-4_s-14\",\n        \"han-fei-zi_ch-49_p-4_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"古的人或事文王處豐、鎬的間，地方百里，行仁義而且懷西戎，遂王天下。徐偃王處漢東，地方五百里，行仁義，割地而且朝的人或事三十有六國，荊文王恐他的害己啊，舉兵伐徐，遂滅的。所以文王行仁義而且王天下，偃王行仁義而且喪他的國，是仁義用於古不用於今啊。因此韓絕不是子評論說道：世異則事異。當舜的時，有苗不服，禹將伐的，舜說道：不可。上德不厚而且行武，絕不是道啊。乃修教三年，執干戚舞，有苗乃服。共工的戰，鐵銛矩的人或事及乎敵，鎧甲不堅的人或事傷乎體，是干戚用於古不用於今啊。因此韓絕不是子評論說道：事異則備變。上古競於道德，中世逐於智謀，當今爭於氣力。齊將攻魯，魯使子貢說的，齊人說道：子言絕不是不辯啊，吾所欲的人或事土地啊，絕不是斯言所謂啊。遂舉兵伐魯，去門十里以為界。所以偃王仁義而且徐亡，子貢辯智而且魯削。以是言的，夫仁義辯智，絕不是所以持國啊。去偃王的仁，息子貢的智，循徐、魯的力使敵萬乘，則齊、荊的慾不得行於二國矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「古者文王處豐、鎬之間，地方百里，行仁義而懷西戎，遂王天下」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「古」、「文」、「王」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「古者文王處豐鎬之間地方百里行仁義而懷西戎遂王天下」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「徐偃王處漢東，地方五百里，行仁義，割地而朝者三十有六國，荊文王恐其害己也，舉兵伐徐，遂滅之」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 5,\n      \"canonicalText\": \"夫古今異俗，新故異備，如欲以寬緩之政、治急世之民，猶無轡策而御駻馬，此不知之患也。今儒、墨皆稱先王兼愛天下，則視民如父母。何以明其然也？曰：「司寇行刑，君為之不舉樂；聞死刑之報，君為流涕。」此所舉先王也。夫以君臣為如父子則必治，推是言之，是無亂父子也。人之情性，莫先於父母，皆見愛而未必治也，雖厚愛矣，奚遽不亂？今先王之愛民，不過父母之愛子，子未必不亂也，則民奚遽治哉！且夫以法行刑而君為之流涕，此以效仁，非以為治也。夫垂泣不欲刑者仁也，然而不可不刑者法也，先王勝其法不聽其泣，則仁之不可以為治亦明矣。且民者固服於勢，寡能懷於義。仲尼，天下聖人也，修行明道以遊海內，海內說其仁，美其義，而為服役者七十人，蓋貴仁者寡，能義者難也。故以天下之大，而為服役者七十人，而仁義者一人。魯哀公，下主也，南面君國，境內之民莫敢不臣。民者固服於勢，誠易以服人，故仲尼反為臣，而哀公顧為君。仲尼非懷其義，服其勢也。故以義則仲尼不服於哀公，乘勢則哀公臣仲尼。今學者之說人主也，不乘必勝之勢，而務行仁義則可以王，是求人主之必及仲尼，而以世之凡民皆如列徒，此必不得之數也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-5_s-1\",\n        \"han-fei-zi_ch-49_p-5_s-2\",\n        \"han-fei-zi_ch-49_p-5_s-3\",\n        \"han-fei-zi_ch-49_p-5_s-4\",\n        \"han-fei-zi_ch-49_p-5_s-5\",\n        \"han-fei-zi_ch-49_p-5_s-6\",\n        \"han-fei-zi_ch-49_p-5_s-7\",\n        \"han-fei-zi_ch-49_p-5_s-8\",\n        \"han-fei-zi_ch-49_p-5_s-9\",\n        \"han-fei-zi_ch-49_p-5_s-10\",\n        \"han-fei-zi_ch-49_p-5_s-11\",\n        \"han-fei-zi_ch-49_p-5_s-12\",\n        \"han-fei-zi_ch-49_p-5_s-13\",\n        \"han-fei-zi_ch-49_p-5_s-14\",\n        \"han-fei-zi_ch-49_p-5_s-15\",\n        \"han-fei-zi_ch-49_p-5_s-16\",\n        \"han-fei-zi_ch-49_p-5_s-17\",\n        \"han-fei-zi_ch-49_p-5_s-18\",\n        \"han-fei-zi_ch-49_p-5_s-19\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"夫古今異俗，新所以異備，如欲以寬緩的政、治急世的民，猶無轡策而且御駻馬，此不知的患啊。今儒、墨皆稱先王兼愛天下，則視民如父母。何以明他的然啊？說道：司寇行刑，國君為的不舉樂；聞死刑的報，國君為流涕。此所舉先王啊。夫以國君臣屬為如父子則必治，推是言的，是無亂父子啊。人的情性，莫先於父母，皆見愛而且未必治啊，雖厚愛矣，奚遽不亂？今先王的愛民，不過父母的愛子，子未必不亂啊，則民奚遽治哉！再的人或事況且以法規法令行刑而且國君為的流涕，此以效仁，絕不是以為治啊。夫垂泣不欲刑的人或事仁啊，然而且不可不刑的人或事法規法令啊，先王勝他的法規法令不聽他的泣，則仁的不可以為治亦明矣。且民的人或事固服於權位威勢，寡能懷於義。仲尼，天下聖人啊，修行明道以遊海內，海內說他的仁，美他的義，而且為服役的人或事七十人，蓋貴仁的人或事寡，能義的人或事難啊。所以以天下的大，而且為服役的人或事七十人，而且仁義的人或事一人。魯哀公，下主啊，南面國君國，境內的民莫敢不臣屬。民的人或事固服於權位威勢，誠易以服人，所以仲尼反為臣屬，而且哀公顧為國君。仲尼絕不是懷他的義，服他的權位威勢啊。所以以義則仲尼不服於哀公，乘權位威勢則哀公臣屬仲尼。今學的人或事的說人主啊，不乘必勝的權位威勢，而且務行仁義則可以王，是求人主的必及仲尼，而且以世的凡民皆如列徒，此必不得的數啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「夫古今異俗，新故異備，如欲以寬緩之政、治急世之民，猶無轡策而御駻馬，此不知之患也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「古」、「今」、「異」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「夫古今異俗新故異備如欲以寬緩之政治急世之民猶無轡」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「今儒、墨皆稱先王兼愛天下，則視民如父母」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 6,\n      \"canonicalText\": \"今有不才之子，父母怒之弗為改，鄉人譙之弗為動，師長教之弗為變。夫以父母之愛，鄉人之行，師長之智，三美加焉，而終不動其脛毛，不改；州部之吏，操官兵、推公法而求索姦人，然後恐懼，變其節，易其行矣。故父母之愛不足以教子，必待州部之嚴刑者，民固驕於愛、聽於威矣。故十仞之城，樓季弗能踰者，峭也；千仞之山，跛牂易牧者，夷也。故明王峭其法、而嚴其刑也。布帛尋常，庸人不釋；鑠金百溢，盜跖不掇。不必害則不釋尋常，必害手則不掇百溢，故明主必其誅也。是以賞莫如厚而信，使民利之；罰莫如重而必，使民畏之；法莫如一而固，使民知之。故主施賞不遷，行誅無赦。譽輔其賞，毀隨其罰，則賢不肖俱盡其力矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-6_s-1\",\n        \"han-fei-zi_ch-49_p-6_s-2\",\n        \"han-fei-zi_ch-49_p-6_s-3\",\n        \"han-fei-zi_ch-49_p-6_s-4\",\n        \"han-fei-zi_ch-49_p-6_s-5\",\n        \"han-fei-zi_ch-49_p-6_s-6\",\n        \"han-fei-zi_ch-49_p-6_s-7\",\n        \"han-fei-zi_ch-49_p-6_s-8\",\n        \"han-fei-zi_ch-49_p-6_s-9\",\n        \"han-fei-zi_ch-49_p-6_s-10\",\n        \"han-fei-zi_ch-49_p-6_s-11\",\n        \"han-fei-zi_ch-49_p-6_s-12\",\n        \"han-fei-zi_ch-49_p-6_s-13\",\n        \"han-fei-zi_ch-49_p-6_s-14\",\n        \"han-fei-zi_ch-49_p-6_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今有不才的子，父母怒的弗為改，鄉人譙的弗為動，師長教的弗為變。夫以父母的愛，鄉人的行，師長的智，三美加焉，而且終不動他的脛毛，不改；州部的吏，操官兵、推公法規法令而且求索姦人，然後恐懼，變他的節，易他的行矣。所以父母的愛不足以教子，必待州部的嚴刑的人或事，民固驕於愛、聽於威矣。所以十仞的城，樓季弗能踰的人或事，峭啊；千仞的山，跛牂易牧的人或事，夷啊。所以明王峭他的法規法令、而且嚴他的刑啊。布帛尋常，庸人不釋；鑠金百溢，盜跖不掇。不必害則不釋尋常，必害手則不掇百溢，所以明主必他的誅啊。是以賞賜莫如厚而且信，使民利的；刑罰莫如重而且必，使民畏的；法規法令莫如一而且固，使民知的。所以主施賞賜不遷，行誅無赦。譽輔他的賞賜，毀隨他的刑罰，則賢不肖俱盡他的力矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「今有不才之子，父母怒之弗為改，鄉人譙之弗為動，師長教之弗為變」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「有」、「不」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今有不才之子父母怒之弗為改鄉人譙之弗為動師長教之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫以父母之愛，鄉人之行，師長之智，三美加焉，而終不動其脛毛，不改」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 7,\n      \"canonicalText\": \"今則不然，以其有功也爵之，而卑其士官也；以其耕作也賞之，而少其家業也；以其不收也外之，而高其輕世也；以其犯禁也罪之，而多其有勇也。毀譽、賞罰之所加者相與悖繆也，故法禁壞而民愈亂。今兄弟被侵必攻者廉也，知友被辱隨仇者貞也，廉貞之行成，而君上之法犯矣。人主尊貞廉之行，而忘犯禁之罪，故民程於勇而吏不能勝也。不事力而衣食則謂之能，不戰功而尊則謂之賢，賢能之行成而兵弱而地荒矣。人主說賢能之行，而忘兵弱地荒之禍，則私行立而公利滅矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-7_s-1\",\n        \"han-fei-zi_ch-49_p-7_s-2\",\n        \"han-fei-zi_ch-49_p-7_s-3\",\n        \"han-fei-zi_ch-49_p-7_s-4\",\n        \"han-fei-zi_ch-49_p-7_s-5\",\n        \"han-fei-zi_ch-49_p-7_s-6\",\n        \"han-fei-zi_ch-49_p-7_s-7\",\n        \"han-fei-zi_ch-49_p-7_s-8\",\n        \"han-fei-zi_ch-49_p-7_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今則不然，以他的有功啊爵的，而且卑他的士官啊；以他的耕作啊賞賜的，而且少他的家業啊；以他的不收啊外的，而且高他的輕世啊；以他的犯禁啊罪的，而且多他的有勇啊。毀譽、賞賜與刑罰的所加的人或事相與悖繆啊，所以法規法令禁壞而且民愈亂。今兄弟被侵必攻的人或事廉啊，知友被辱隨仇的人或事貞啊，廉貞的行成，而且國君上的法規法令犯矣。人主尊貞廉的行，而且忘犯禁的罪，所以民程於勇而且吏不能勝啊。不事力而且衣食則謂的能，不戰功而且尊則謂的賢，賢能的行成而且兵弱而且地荒矣。人主說賢能的行，而且忘兵弱地荒的禍，則私行立而且公利滅矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「今則不然，以其有功也爵之，而卑其士官也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「不」、「然」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今則不然以其有功也爵之而卑其士官也以其耕作也賞之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「以其耕作也賞之，而少其家業也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 8,\n      \"canonicalText\": \"儒以文亂法，俠以武犯禁，而人主兼禮之，此所以亂也。夫離法者罪，而諸先生以文學取；犯禁者誅，而羣俠以私劍養。故法之所非，君之所取；吏之所誅，上之所養也。法趣上下四相反也，而無所定，雖有十黃帝不能治也。故行仁義者非所譽，譽之則害功；文學者非所用，用之則亂法。楚之有直躬，其父竊羊而謁之吏，令尹曰：「殺之，」以為直於君而曲於父，報而罪之。以是觀之，夫君之直臣，父之暴子也。魯人從君戰，三戰三北，仲尼問其故，對曰：「吾有老父，身死莫之養也。」仲尼以為孝，舉而上之。以是觀之，夫父之孝子，君之背臣也。故令尹誅而楚姦不上聞，仲尼賞而魯民易降北。上下之利若是其異也，而人主兼舉匹夫之行，而求致社稷之福，必不幾矣。古者蒼頡之作書也，自環者謂之私，背私謂之公，公私之相背也，乃蒼頡固以知之矣。今以為同利者，不察之患也。然則為匹夫計者，莫如脩行義而習文學。行義脩則見信，見信則受事；文學習則為明師，為明師則顯榮；此匹夫之美也。然則無功而受事，無爵而顯榮，為有政如此，則國必亂，主必危矣。故不相容之事，不兩立也。斬敵者受賞，而高慈惠之行；拔城者受爵祿，而信廉愛之說；堅甲厲兵以備難，而美薦紳之飾；富國以農，距敵恃卒，而貴文學之士；廢敬上畏法之民，而養遊俠私劍之屬。舉行如此，治強不可得也。國平養儒俠，難至用介士，所利非所用，所用非所利。是故服事者簡其業，而遊學者日眾，是世之所以亂也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-8_s-1\",\n        \"han-fei-zi_ch-49_p-8_s-2\",\n        \"han-fei-zi_ch-49_p-8_s-3\",\n        \"han-fei-zi_ch-49_p-8_s-4\",\n        \"han-fei-zi_ch-49_p-8_s-5\",\n        \"han-fei-zi_ch-49_p-8_s-6\",\n        \"han-fei-zi_ch-49_p-8_s-7\",\n        \"han-fei-zi_ch-49_p-8_s-8\",\n        \"han-fei-zi_ch-49_p-8_s-9\",\n        \"han-fei-zi_ch-49_p-8_s-10\",\n        \"han-fei-zi_ch-49_p-8_s-11\",\n        \"han-fei-zi_ch-49_p-8_s-12\",\n        \"han-fei-zi_ch-49_p-8_s-13\",\n        \"han-fei-zi_ch-49_p-8_s-14\",\n        \"han-fei-zi_ch-49_p-8_s-15\",\n        \"han-fei-zi_ch-49_p-8_s-16\",\n        \"han-fei-zi_ch-49_p-8_s-17\",\n        \"han-fei-zi_ch-49_p-8_s-18\",\n        \"han-fei-zi_ch-49_p-8_s-19\",\n        \"han-fei-zi_ch-49_p-8_s-20\",\n        \"han-fei-zi_ch-49_p-8_s-21\",\n        \"han-fei-zi_ch-49_p-8_s-22\",\n        \"han-fei-zi_ch-49_p-8_s-23\",\n        \"han-fei-zi_ch-49_p-8_s-24\",\n        \"han-fei-zi_ch-49_p-8_s-25\",\n        \"han-fei-zi_ch-49_p-8_s-26\",\n        \"han-fei-zi_ch-49_p-8_s-27\",\n        \"han-fei-zi_ch-49_p-8_s-28\",\n        \"han-fei-zi_ch-49_p-8_s-29\",\n        \"han-fei-zi_ch-49_p-8_s-30\",\n        \"han-fei-zi_ch-49_p-8_s-31\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"儒以文亂法規法令，俠以武犯禁，而且人主兼禮的，此所以亂啊。夫離法規法令的人或事罪，而且諸先生以文學取；犯禁的人或事誅，而且羣俠以私劍養。所以法規法令的所絕不是，國君的所取；吏的所誅，上的所養啊。法規法令趣上下四相反啊，而且無所定，雖有十黃帝不能治啊。所以行仁義的人或事絕不是所譽，譽的則害功；文學的人或事絕不是所用，用的則亂法規法令。楚的有直躬，他的父竊羊而且謁的吏，令尹說道：殺的，以為直於國君而且曲於父，報而且罪的。以是觀的，夫國君的直臣屬，父的暴子啊。魯人從國君戰，三戰三北，仲尼問他的所以，對說道：吾有老父，身死莫的養啊。仲尼以為孝，舉而且上的。以是觀的，夫父的孝子，國君的背臣屬啊。所以令尹誅而且楚姦不上聞，仲尼賞賜而且魯民易降北。上下的利若是他的異啊，而且人主兼舉匹夫的行，而且求致社稷的福，必不幾矣。古的人或事蒼頡的作書啊，自環的人或事謂的私，背私謂的公，公私的相背啊，乃蒼頡固以知的矣。今以為同利的人或事，不察的患啊。然則為匹夫計的人或事，莫如脩行義而且習文學。行義脩則見信，見信則受事；文學習則為明師，為明師則顯榮；此匹夫的美啊。然則無功而且受事，無爵而且顯榮，為有政如此，則國必亂，主必危矣。所以不相容的事，不兩立啊。斬敵的人或事受賞賜，而且高慈惠的行；拔城的人或事受爵祿，而且信廉愛的說；堅甲厲兵以備難，而且美薦紳的飾；富國以農，距敵恃卒，而且貴文學的士；廢敬上畏法規法令的民，而且養遊俠私劍的屬。舉行如此，治強不可得啊。國平養儒俠，難至用介士，所利絕不是所用，所用絕不是所利。正因為如此服事的人或事簡他的業，而且遊學的人或事日眾，是世的所以亂啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「儒以文亂法，俠以武犯禁，而人主兼禮之，此所以亂也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「儒」、「文」、「亂」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「儒以文亂法俠以武犯禁而人主兼禮之此所以亂也夫離法」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「夫離法者罪，而諸先生以文學取」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 9,\n      \"canonicalText\": \"且世之所謂賢者，貞信之行也。所謂智者，微妙之言也。微妙之言，上智之所難知也。今為眾人法，而以上智之所難知，則民無從識之矣。故糟糠不飽者不務梁肉，短褐不完者不待文繡。夫治世之事，急者不得，則緩者非所務也。今所治之政，民閒之事，夫婦所明知者不用，而慕上知之論，則其於治反矣。故微妙之言，非民務也。若夫賢良貞信之行者，必將貴不欺之士。不欺之士者，亦無不欺之術也。布衣相與交，無富厚以相利，無威勢以相懼也，故求不欺之士。今人主處制人之勢，有一國之厚，重賞嚴誅，得操其柄，以修明術之所燭，雖有田常、子罕之臣，不敢欺也，奚待於不欺之士？今貞信之士不盈於十，而境內之官以百數，必任貞信之士，則人不足官，人不足官則治者寡而亂者眾矣。故明主之道，一法而不求智，固術而不慕信，故法不敗，而羣官無姦詐矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-9_s-1\",\n        \"han-fei-zi_ch-49_p-9_s-2\",\n        \"han-fei-zi_ch-49_p-9_s-3\",\n        \"han-fei-zi_ch-49_p-9_s-4\",\n        \"han-fei-zi_ch-49_p-9_s-5\",\n        \"han-fei-zi_ch-49_p-9_s-6\",\n        \"han-fei-zi_ch-49_p-9_s-7\",\n        \"han-fei-zi_ch-49_p-9_s-8\",\n        \"han-fei-zi_ch-49_p-9_s-9\",\n        \"han-fei-zi_ch-49_p-9_s-10\",\n        \"han-fei-zi_ch-49_p-9_s-11\",\n        \"han-fei-zi_ch-49_p-9_s-12\",\n        \"han-fei-zi_ch-49_p-9_s-13\",\n        \"han-fei-zi_ch-49_p-9_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"且世的所謂賢的人或事，貞信的行啊。所謂智的人或事，微妙的言啊。微妙的言，上智的所難知啊。今為眾人法規法令，而且以上智的所難知，則民無從識的矣。所以糟糠不飽的人或事不務梁肉，短褐不完的人或事不待文繡。夫治世的事，急的人或事不得，則緩的人或事絕不是所務啊。今所治的政，民閒的事，夫婦所明知的人或事不用，而且慕上知的論，則他的於治反矣。所以微妙的言，絕不是民務啊。至於談到那賢良貞信的行的人或事，必將貴不欺的士。不欺的士的人或事，亦無不欺的督察權術啊。布衣相與交，無富厚以相利，無威權位威勢以相懼啊，所以求不欺的士。今人主處制人的權位威勢，有一國的厚，重賞賜嚴誅，得操他的柄，以修明督察權術的所燭，雖有田常、子罕的臣屬，不敢欺啊，奚待於不欺的士？今貞信的士不盈於十，而且境內的官以百數，必任貞信的士，則人不足官，人不足官則治的人或事寡而且亂的人或事眾矣。所以明主的道，一法規法令而且不求智，固督察權術而且不慕信，所以法規法令不敗，而且羣官無姦詐矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「且世之所謂賢者，貞信之行也」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「且」、「世」、「謂」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「且世之所謂賢者貞信之行也所謂智者微妙之言也微妙之」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「所謂智者，微妙之言也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 10,\n      \"canonicalText\": \"今人主之於言也，說其辯而不求其當焉；其用於行也，美其聲而不責其功焉。是以天下之眾，其談言者務為辯而不周於用，故舉先王言仁義者盈廷，而政不免於亂；行身者競於為高而不合於功，故智士退處巖穴、歸祿不受，而兵不免於弱，政不免於亂，此其故何也？民之所譽，上之所禮，亂國之術也。今境內之民皆言治，藏商、管之法者家有之，而國愈貧，言耕者眾，執耒者寡也；境內皆言兵，藏孫、吳之書者家有之，而兵愈弱，言戰者多，被甲者少也。故明主用其力，不聽其言；賞其功，必禁無用；故民盡死力以從其上。夫耕之用力也勞，而民為之者，曰：可得以富也。戰之為事也危，而民為之者，曰：可得以貴也。今修文學、習言談，則無耕之勞、而有富之實，無戰之危、而有貴之尊，則人孰不為也？是以百人事智而一人用力，事智者眾則法敗，用力者寡則國貧，此世之所以亂也。故明主之國，無書簡之文，以法為教；無先王之語，以吏為師；無私劍之捍，以斬首為勇。是境內之民，其言談者必軌於法，動作者歸之於功，為勇者盡之於軍。是故無事則國富，有事則兵強，此之謂王資。既畜王資而承敵國之舋，超五帝，侔三王者，必此法也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-10_s-1\",\n        \"han-fei-zi_ch-49_p-10_s-2\",\n        \"han-fei-zi_ch-49_p-10_s-3\",\n        \"han-fei-zi_ch-49_p-10_s-4\",\n        \"han-fei-zi_ch-49_p-10_s-5\",\n        \"han-fei-zi_ch-49_p-10_s-6\",\n        \"han-fei-zi_ch-49_p-10_s-7\",\n        \"han-fei-zi_ch-49_p-10_s-8\",\n        \"han-fei-zi_ch-49_p-10_s-9\",\n        \"han-fei-zi_ch-49_p-10_s-10\",\n        \"han-fei-zi_ch-49_p-10_s-11\",\n        \"han-fei-zi_ch-49_p-10_s-12\",\n        \"han-fei-zi_ch-49_p-10_s-13\",\n        \"han-fei-zi_ch-49_p-10_s-14\",\n        \"han-fei-zi_ch-49_p-10_s-15\",\n        \"han-fei-zi_ch-49_p-10_s-16\",\n        \"han-fei-zi_ch-49_p-10_s-17\",\n        \"han-fei-zi_ch-49_p-10_s-18\",\n        \"han-fei-zi_ch-49_p-10_s-19\",\n        \"han-fei-zi_ch-49_p-10_s-20\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今人主的於言啊，說他的辯而且不求他的當焉；他的用於行啊，美他的聲而且不責他的功焉。是以天下的眾，他的談言的人或事務為辯而且不周於用，所以舉先王言仁義的人或事盈廷，而且政不免於亂；行身的人或事競於為高而且不合於功，所以智士退處巖穴、歸祿不受，而且兵不免於弱，政不免於亂，此他的所以何啊？民的所譽，上的所禮，亂國的督察權術啊。今境內的民皆言治，藏商、管的法規法令的人或事家有的，而且國愈貧，言耕的人或事眾，執耒的人或事寡啊；境內皆言兵，藏孫、吳的書的人或事家有的，而且兵愈弱，言戰的人或事多，被甲的人或事少啊。所以明主用他的力，不聽他的言；賞賜他的功，必禁無用；所以民盡死力以從他的上。夫耕的用力啊勞，而且民為的的人或事，說道：可得以富啊。戰的為事啊危，而且民為的的人或事，說道：可得以貴啊。今修文學、習言談，則無耕的勞、而且有富的實，無戰的危、而且有貴的尊，則人孰不為啊？是以百人事智而且一人用力，事智的人或事眾則法規法令敗，用力的人或事寡則國貧，此世的所以亂啊。所以明主的國，無書簡的文，以法規法令為教；無先王的語，以吏為師；無私劍的捍，以斬首為勇。是境內的民，他的言談的人或事必軌於法規法令，動作的人或事歸的於功，為勇的人或事盡的於軍。正因為如此無事則國富，有事則兵強，此的謂王資。既畜王資而且承敵國的舋，超五帝，侔三王的人或事，必此法規法令啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「今人主之於言也，說其辯而不求其當焉」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「人」、「主」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今人主之於言也說其辯而不求其當焉其用於行也美其聲」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「其用於行也，美其聲而不責其功焉」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 11,\n      \"canonicalText\": \"今則不然，士民縱恣於內，言談者為勢於外，外內稱惡以待強敵，不亦殆乎！故群臣之言外事者，非有分於從衡之黨，則有仇讎之忠，而借力於國也。從者，合眾弱以攻一強也；而衡者，事一強以攻眾弱也；皆非所以持國也。今人臣之言衡者皆曰：「不事大則遇敵受禍矣。」事大未必有實，則舉圖而委，效璽而請兵矣。獻圖則地削，效璽則名卑，地削則國削，名卑則政亂矣。事大為衡未見其利也，而亡地亂政矣。人臣之言從者皆曰：「不救小而伐大則失天下，失天下則國危，國危而主卑。」救小未必有實，則起兵而敵大矣。救小未必能存，而交大未必不有疏，有疏則為強國制矣。出兵則軍敗，退守則城拔，救小為從未見其利，而亡地敗軍矣。是故事強則以外權士官於內，救小則以內重求利於外，國利未立，封土厚祿至矣；主上雖卑，人臣尊矣；國地雖削，私家富矣。事成則以權長重，事敗則以富退處。人主之於其聽說也，於其臣，事未成則爵祿已尊矣；事敗而弗誅，則遊說之士，孰不為用矰繳之說而徼倖其後？故破國亡主以聽言談者之浮說，此其故何也？是人君不明乎公私之利，不察當否之言，而誅罰不必其後也。皆曰「外事大可以王，小可以安。」夫王者，能攻人者也；而安，則不可攻也。強，則能攻人者也；治，則不可攻也。治強不可責於外，內政之有也。今不行法術於內，而事智於外，則不至於治強矣。鄙諺曰：「長袖善舞，多錢善賈。」此言多資之易為工也。故治強易為謀，弱亂難為計。故用於秦者十變而謀希失，用於燕者一變而計希得，非用於秦者必智，用於燕者必愚也，蓋治亂之資異也。故周去秦為從，期年而舉；衛離魏為衡，半歲而亡。是周滅於從，衛亡於衡也。使周、衛緩其從衡之計，而嚴其境內之治，明其法禁，必其賞罰，盡其地力以多其積，致其民死以堅其城守，天下得其地則其利少，攻其國則其傷大，萬乘之國、莫敢自頓於堅城之下，而使強敵裁其弊也，此必不亡之術也。舍必不亡之術而道必滅之事，治國者之過也。智困於內而政亂於外，則亡不可振也。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-11_s-1\",\n        \"han-fei-zi_ch-49_p-11_s-2\",\n        \"han-fei-zi_ch-49_p-11_s-3\",\n        \"han-fei-zi_ch-49_p-11_s-4\",\n        \"han-fei-zi_ch-49_p-11_s-5\",\n        \"han-fei-zi_ch-49_p-11_s-6\",\n        \"han-fei-zi_ch-49_p-11_s-7\",\n        \"han-fei-zi_ch-49_p-11_s-8\",\n        \"han-fei-zi_ch-49_p-11_s-9\",\n        \"han-fei-zi_ch-49_p-11_s-10\",\n        \"han-fei-zi_ch-49_p-11_s-11\",\n        \"han-fei-zi_ch-49_p-11_s-12\",\n        \"han-fei-zi_ch-49_p-11_s-13\",\n        \"han-fei-zi_ch-49_p-11_s-14\",\n        \"han-fei-zi_ch-49_p-11_s-15\",\n        \"han-fei-zi_ch-49_p-11_s-16\",\n        \"han-fei-zi_ch-49_p-11_s-17\",\n        \"han-fei-zi_ch-49_p-11_s-18\",\n        \"han-fei-zi_ch-49_p-11_s-19\",\n        \"han-fei-zi_ch-49_p-11_s-20\",\n        \"han-fei-zi_ch-49_p-11_s-21\",\n        \"han-fei-zi_ch-49_p-11_s-22\",\n        \"han-fei-zi_ch-49_p-11_s-23\",\n        \"han-fei-zi_ch-49_p-11_s-24\",\n        \"han-fei-zi_ch-49_p-11_s-25\",\n        \"han-fei-zi_ch-49_p-11_s-26\",\n        \"han-fei-zi_ch-49_p-11_s-27\",\n        \"han-fei-zi_ch-49_p-11_s-28\",\n        \"han-fei-zi_ch-49_p-11_s-29\",\n        \"han-fei-zi_ch-49_p-11_s-30\",\n        \"han-fei-zi_ch-49_p-11_s-31\",\n        \"han-fei-zi_ch-49_p-11_s-32\",\n        \"han-fei-zi_ch-49_p-11_s-33\",\n        \"han-fei-zi_ch-49_p-11_s-34\",\n        \"han-fei-zi_ch-49_p-11_s-35\",\n        \"han-fei-zi_ch-49_p-11_s-36\",\n        \"han-fei-zi_ch-49_p-11_s-37\",\n        \"han-fei-zi_ch-49_p-11_s-38\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"今則不然，士民縱恣於內，言談的人或事為權位威勢於外，外內稱惡以待強敵，不亦殆乎！所以群臣屬的言外事的人或事，絕不是有分於從衡的黨，則有仇讎的忠，而且借力於國啊。從的人或事，合眾弱以攻一強啊；而且衡的人或事，事一強以攻眾弱啊；皆絕不是所以持國啊。今人臣屬的言衡的人或事皆說道：不事大則遇敵受禍矣。事大未必有實，則舉圖而且委，效璽而且請兵矣。獻圖則地削，效璽則名卑，地削則國削，名卑則政亂矣。事大為衡未見他的利啊，而且亡地亂政矣。人臣屬的言從的人或事皆說道：不救小而且伐大則失天下，失天下則國危，國危而且主卑。救小未必有實，則起兵而且敵大矣。救小未必能存，而且交大未必不有疏，有疏則為強國制矣。出兵則軍敗，退守則城拔，救小為從未見他的利，而且亡地敗軍矣。正因為如此事強則以外權士官於內，救小則以內重求利於外，國利未立，封土厚祿至矣；主上雖卑，人臣屬尊矣；國地雖削，私家富矣。事成則以權長重，事敗則以富退處。人主的於他的聽說啊，於他的臣屬，事未成則爵祿已尊矣；事敗而且弗誅，則遊說的士，孰不為用矰繳的說而且徼倖他的後？所以破國亡主以聽言談的人或事的浮說，此他的所以何啊？是人國君不明乎公私的利，不察當否的言，而且誅刑罰不必他的後啊。皆說道：外事大可以王，小可以安。夫王的人或事，能攻人的人或事啊；而且安，則不可攻啊。強，則能攻人的人或事啊；治，則不可攻啊。治強不可責於外，內政的有啊。今不行法規法令督察權術於內，而且事智於外，則不至於治強矣。鄙諺說道：長袖善舞，多錢善賈。此言多資的易為工啊。所以治強易為謀，弱亂難為計。所以用於秦的人或事十變而且謀希失，用於燕的人或事一變而且計希得，絕不是用於秦的人或事必智，用於燕的人或事必愚啊，蓋治亂的資異啊。所以周去秦為從，期年而且舉；衛離魏為衡，半歲而且亡。是周滅於從，衛亡於衡啊。使周、衛緩他的從衡的計，而且嚴他的境內的治，明他的法規法令禁，必他的賞賜與刑罰，盡他的地力以多他的積，致他的民死以堅他的城守，天下得他的地則他的利少，攻他的國則他的傷大，萬乘的國、莫敢自頓於堅城的下，而且使強敵裁他的弊啊，此必不亡的督察權術啊。舍必不亡的督察權術而且道必滅的事，治國的人或事的過啊。智困於內而且政亂於外，則亡不可振啊。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「今則不然，士民縱恣於內，言談者為勢於外，外內稱惡以待強敵，不亦殆乎」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「今」、「不」、「然」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「今則不然士民縱恣於內言談者為勢於外外內稱惡以待強」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「故群臣之言外事者，非有分於從衡之黨，則有仇讎之忠，而借力於國也」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 12,\n      \"canonicalText\": \"民之故計，皆就安利如闢危窮。今為之攻戰，進則死於敵，退則死於誅則危矣。棄私家之事而必汗馬之勞，家困而上弗論則窮矣。窮危之所在也，民安得勿避。故事私門而完解舍，解舍完則遠戰，遠戰則安。行貨賂而襲當塗者則求得，求得則私安，私安則利之所在，安得勿就？是以公民少而私人眾矣。夫明王治國之政，使其商工遊食之民少而名卑，以寡趣本務而趨末作。今世近習之請行則官爵可買，官爵可買則商工不卑也矣；姦財貨賈得用於市則商人不少矣。聚斂倍農而致尊過耕戰之士，則耿介之士寡而高價之民多矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-12_s-1\",\n        \"han-fei-zi_ch-49_p-12_s-2\",\n        \"han-fei-zi_ch-49_p-12_s-3\",\n        \"han-fei-zi_ch-49_p-12_s-4\",\n        \"han-fei-zi_ch-49_p-12_s-5\",\n        \"han-fei-zi_ch-49_p-12_s-6\",\n        \"han-fei-zi_ch-49_p-12_s-7\",\n        \"han-fei-zi_ch-49_p-12_s-8\",\n        \"han-fei-zi_ch-49_p-12_s-9\",\n        \"han-fei-zi_ch-49_p-12_s-10\",\n        \"han-fei-zi_ch-49_p-12_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"民的所以計，皆就安利如闢危窮。今為的攻戰，進則死於敵，退則死於誅則危矣。棄私家的事而且必汗馬的勞，家困而且上弗論則窮矣。窮危的所在啊，民安得勿避。所以事私門而且完解舍，解舍完則遠戰，遠戰則安。行貨賂而且襲當塗的人或事則求得，求得則私安，私安則利的所在，安得勿就？是以公民少而且私人眾矣。夫明王治國的政，使他的商工遊食的民少而且名卑，以寡趣本務而且趨末作。今世近習的請行則官爵可買，官爵可買則商工不卑啊矣；姦財貨賈得用於市則商人不少矣。聚斂倍農而且致尊過耕戰的士，則耿介的士寡而且高價的民多矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「民之故計，皆就安利如闢危窮」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「民」、「計」、「皆」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「民之故計皆就安利如闢危窮今為之攻戰進則死於敵退則」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「今為之攻戰，進則死於敵，退則死於誅則危矣」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"order\": 13,\n      \"canonicalText\": \"是故亂國之俗，其學者則稱先王之道，以籍仁義，盛容服而飾辯說，以疑當世之法而貳人主之心。其言古者，為設詐稱，借於外力，以成其私而遺社稷之利。其帶劍者，聚徒屬，立節操，以顯其名而犯五官之禁。其患御者，積於私門，盡貨賂而用重人之謁，退汗馬之勞。其商工之民，修治苦窳之器，聚弗靡之財，蓄積待時而侔農夫之利。此五者，邦之蠹也。人主不除此五蠹之民，不養耿介之士，則海內雖有破亡之國，削滅之朝，亦勿怪矣。\",\n      \"sentenceIds\": [\n        \"han-fei-zi_ch-49_p-13_s-1\",\n        \"han-fei-zi_ch-49_p-13_s-2\",\n        \"han-fei-zi_ch-49_p-13_s-3\",\n        \"han-fei-zi_ch-49_p-13_s-4\",\n        \"han-fei-zi_ch-49_p-13_s-5\",\n        \"han-fei-zi_ch-49_p-13_s-6\",\n        \"han-fei-zi_ch-49_p-13_s-7\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《韓非子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先慎《韓非子集解》本\",\n          \"location\": \"https://ctext.org/hanfeizi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《韓非子》—維基文庫\",\n          \"edition\": \"四部叢刊景宋本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/韓非子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"正因為如此亂國的俗，他的學的人或事則稱先王的道，以籍仁義，盛容服而且飾辯說，以疑當世的法規法令而且貳人主的心。他的言古的人或事，為設詐稱，借於外力，以成他的私而且遺社稷的利。他的帶劍的人或事，聚徒屬，立節操，以顯他的名而且犯五官的禁。他的患御的人或事，積於私門，盡貨賂而且用重人的謁，退汗馬的勞。他的商工的民，修治苦窳的器，聚弗靡的財，蓄積待時而且侔農夫的利。此五的人或事，邦的蠹啊。人主不除此五蠹的民，不養耿介的士，則海內雖有破亡的國，削滅的朝，亦勿怪矣。\",\n        \"analysis\": \"【篇章題解與歷史語境】\\n本節選自先秦法家集大成之鴻篇巨著《韓非子》〈五蠹〉。韓非深刻融合法、術、勢三大治國精要，此處「是故亂國之俗，其學者則稱先王之道，以籍仁義，盛容服而飾辯說，以疑當世之法而貳人主之心」直擊戰國晚期諸侯爭霸與官僚體系博弈之核心實態。\\n\\n【法術名物與冷峻訓詁】\\n依清王先慎《韓非子集解》與陳奇猷《韓非子集釋》，深究「是」、「亂」、「國」等權柄操縱樞紐，嚴格辨明君臣利害對立實然，強調二柄在手、刑賞分明、名實相參之嚴密政法機制。\\n\\n【論辯邏輯與法家章法】\\n全文說理如霜雪般冷靜嚴峻，引述「是故亂國之俗其學者則稱先王之道以籍仁義盛容服而飾」層層剖析，立足人皆自為趨利避害之實然人性，文鋒銳利透闢，以嚴謹排比與歷史事例揭示治亂安危之樞軸，具有震撼人心之邏輯力量。\\n\\n【政治哲學與制度評析】\\n「其言古者，為設詐稱，借於外力，以成其私而遺社稷之利」總結古代中央集權君主統治與官僚監察制度之深層密碼，主法不主私、任法去私意，為理解先秦法家法治現代化轉型與傳統法制思想提供極具理性深度之制度史鑑。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"上古之世，人民少而禽獸眾，人民不勝禽獸蟲蛇，有聖人作，搆木為巢以避羣害，而民悅之，使王天下，號曰有巢氏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"民食果蓏蚌蛤，腥臊惡臭而傷害腹胃，民多疾病，有聖人作，鑽燧取火以化腥臊，而民說之，使王天下，號之曰燧人氏。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"中古之世，天下大水，而鯀、禹決瀆。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"近古之世，桀、紂暴亂，而湯、武征伐。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"今有搆木鑽燧於夏后氏之世者，必為鯀、禹笑矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"有決瀆於殷、周之世者，必為湯、武笑矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 7,\n      \"canonicalText\": \"然則今有美堯、舜、湯、武、禹之道於當今之世者，必為新聖笑矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 8,\n      \"canonicalText\": \"是以聖人不期脩古，不法常可，論世之事，因為之備。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 9,\n      \"canonicalText\": \"宋人有耕田者，田中有株，兔走，觸株折頸而死，因釋其耒而守株，冀復得兔，兔不可復得，而身為宋國笑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-1_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-1\",\n      \"order\": 10,\n      \"canonicalText\": \"今欲以先王之政，治當世之民，皆守株之類也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-2_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"古者丈夫不耕，草木之實足食也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-2_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"婦人不織，禽獸之皮足衣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-2_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"不事力而養足，人民少而財有餘，故民不爭。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-2_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"是以厚賞不行，重罰不用而民自治。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-2_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"今人有五子不為多，子又有五子，大父未死而有二十五孫，是以人民眾而貨財寡，事力勞而供養薄，故民爭，雖倍賞累罰而不免於亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"堯之王天下也，茅茨不翦，采椽不斲，糲粢之食，藜藿之羹，冬日麑裘，夏日葛衣，雖監門之服養，不虧於此矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"禹之王天下也，身執耒臿以為民先，股無胈，脛不生毛，雖臣虜之勞不苦於此矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"以是言之，夫古之讓天子者，是去監門之養而離臣虜之勞也，古傳天下而不足多也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"今之縣令，一日身死，子孫累世絜駕，故人重之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"是以人之於讓也，輕辭古之天子，難去今之縣令者，薄厚之實異也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"夫山居而谷汲者，膢臘而相遺以水；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"澤居苦水者，買庸而決竇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"故饑歲之春，幼弟不饟；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"穰歲之秋，疏客必食；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 10,\n      \"canonicalText\": \"非疏骨肉愛過客也，多少之實異也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 11,\n      \"canonicalText\": \"是以古之易財，非仁也，財多也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 12,\n      \"canonicalText\": \"今之爭奪，非鄙也，財寡也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 13,\n      \"canonicalText\": \"輕辭天子，非高也，勢薄也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 14,\n      \"canonicalText\": \"爭土橐，非下也，權重也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 15,\n      \"canonicalText\": \"故聖人議多少、論薄厚為之政，故罰薄不為慈，誅嚴不為戾，稱俗而行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-3_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-3\",\n      \"order\": 16,\n      \"canonicalText\": \"故事因於世，而備適於事。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"古者文王處豐、鎬之間，地方百里，行仁義而懷西戎，遂王天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"徐偃王處漢東，地方五百里，行仁義，割地而朝者三十有六國，荊文王恐其害己也，舉兵伐徐，遂滅之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"故文王行仁義而王天下，偃王行仁義而喪其國，是仁義用於古不用於今也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"故曰：世異則事異。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"當舜之時，有苗不服，禹將伐之，舜曰：「不可。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"上德不厚而行武，非道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"」乃修教三年，執干戚舞，有苗乃服。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"共工之戰，鐵銛矩者及乎敵，鎧甲不堅者傷乎體，是干戚用於古不用於今也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"故曰：事異則備變。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 10,\n      \"canonicalText\": \"上古競於道德，中世逐於智謀，當今爭於氣力。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 11,\n      \"canonicalText\": \"齊將攻魯，魯使子貢說之，齊人曰：「子言非不辯也，吾所欲者土地也，非斯言所謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 12,\n      \"canonicalText\": \"」遂舉兵伐魯，去門十里以為界。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 13,\n      \"canonicalText\": \"故偃王仁義而徐亡，子貢辯智而魯削。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 14,\n      \"canonicalText\": \"以是言之，夫仁義辯智，非所以持國也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-4_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-4\",\n      \"order\": 15,\n      \"canonicalText\": \"去偃王之仁，息子貢之智，循徐、魯之力使敵萬乘，則齊、荊之慾不得行於二國矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"夫古今異俗，新故異備，如欲以寬緩之政、治急世之民，猶無轡策而御駻馬，此不知之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"今儒、墨皆稱先王兼愛天下，則視民如父母。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 3,\n      \"canonicalText\": \"何以明其然也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 4,\n      \"canonicalText\": \"曰：「司寇行刑，君為之不舉樂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 5,\n      \"canonicalText\": \"聞死刑之報，君為流涕。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 6,\n      \"canonicalText\": \"」此所舉先王也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 7,\n      \"canonicalText\": \"夫以君臣為如父子則必治，推是言之，是無亂父子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 8,\n      \"canonicalText\": \"人之情性，莫先於父母，皆見愛而未必治也，雖厚愛矣，奚遽不亂？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 9,\n      \"canonicalText\": \"今先王之愛民，不過父母之愛子，子未必不亂也，則民奚遽治哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 10,\n      \"canonicalText\": \"且夫以法行刑而君為之流涕，此以效仁，非以為治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 11,\n      \"canonicalText\": \"夫垂泣不欲刑者仁也，然而不可不刑者法也，先王勝其法不聽其泣，則仁之不可以為治亦明矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 12,\n      \"canonicalText\": \"且民者固服於勢，寡能懷於義。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 13,\n      \"canonicalText\": \"仲尼，天下聖人也，修行明道以遊海內，海內說其仁，美其義，而為服役者七十人，蓋貴仁者寡，能義者難也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 14,\n      \"canonicalText\": \"故以天下之大，而為服役者七十人，而仁義者一人。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 15,\n      \"canonicalText\": \"魯哀公，下主也，南面君國，境內之民莫敢不臣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 16,\n      \"canonicalText\": \"民者固服於勢，誠易以服人，故仲尼反為臣，而哀公顧為君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 17,\n      \"canonicalText\": \"仲尼非懷其義，服其勢也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 18,\n      \"canonicalText\": \"故以義則仲尼不服於哀公，乘勢則哀公臣仲尼。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-5_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-5\",\n      \"order\": 19,\n      \"canonicalText\": \"今學者之說人主也，不乘必勝之勢，而務行仁義則可以王，是求人主之必及仲尼，而以世之凡民皆如列徒，此必不得之數也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"今有不才之子，父母怒之弗為改，鄉人譙之弗為動，師長教之弗為變。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"夫以父母之愛，鄉人之行，師長之智，三美加焉，而終不動其脛毛，不改；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"州部之吏，操官兵、推公法而求索姦人，然後恐懼，變其節，易其行矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"故父母之愛不足以教子，必待州部之嚴刑者，民固驕於愛、聽於威矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"故十仞之城，樓季弗能踰者，峭也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"千仞之山，跛牂易牧者，夷也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"故明王峭其法、而嚴其刑也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"布帛尋常，庸人不釋；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 9,\n      \"canonicalText\": \"鑠金百溢，盜跖不掇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 10,\n      \"canonicalText\": \"不必害則不釋尋常，必害手則不掇百溢，故明主必其誅也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 11,\n      \"canonicalText\": \"是以賞莫如厚而信，使民利之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 12,\n      \"canonicalText\": \"罰莫如重而必，使民畏之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 13,\n      \"canonicalText\": \"法莫如一而固，使民知之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 14,\n      \"canonicalText\": \"故主施賞不遷，行誅無赦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-6_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-6\",\n      \"order\": 15,\n      \"canonicalText\": \"譽輔其賞，毀隨其罰，則賢不肖俱盡其力矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"今則不然，以其有功也爵之，而卑其士官也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"以其耕作也賞之，而少其家業也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"以其不收也外之，而高其輕世也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"以其犯禁也罪之，而多其有勇也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"毀譽、賞罰之所加者相與悖繆也，故法禁壞而民愈亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"今兄弟被侵必攻者廉也，知友被辱隨仇者貞也，廉貞之行成，而君上之法犯矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"人主尊貞廉之行，而忘犯禁之罪，故民程於勇而吏不能勝也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"不事力而衣食則謂之能，不戰功而尊則謂之賢，賢能之行成而兵弱而地荒矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-7_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"人主說賢能之行，而忘兵弱地荒之禍，則私行立而公利滅矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"儒以文亂法，俠以武犯禁，而人主兼禮之，此所以亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"夫離法者罪，而諸先生以文學取；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"犯禁者誅，而羣俠以私劍養。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"故法之所非，君之所取；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"吏之所誅，上之所養也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"法趣上下四相反也，而無所定，雖有十黃帝不能治也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"故行仁義者非所譽，譽之則害功；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"文學者非所用，用之則亂法。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"楚之有直躬，其父竊羊而謁之吏，令尹曰：「殺之，」以為直於君而曲於父，報而罪之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"以是觀之，夫君之直臣，父之暴子也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"魯人從君戰，三戰三北，仲尼問其故，對曰：「吾有老父，身死莫之養也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 12,\n      \"canonicalText\": \"」仲尼以為孝，舉而上之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 13,\n      \"canonicalText\": \"以是觀之，夫父之孝子，君之背臣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 14,\n      \"canonicalText\": \"故令尹誅而楚姦不上聞，仲尼賞而魯民易降北。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 15,\n      \"canonicalText\": \"上下之利若是其異也，而人主兼舉匹夫之行，而求致社稷之福，必不幾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 16,\n      \"canonicalText\": \"古者蒼頡之作書也，自環者謂之私，背私謂之公，公私之相背也，乃蒼頡固以知之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 17,\n      \"canonicalText\": \"今以為同利者，不察之患也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 18,\n      \"canonicalText\": \"然則為匹夫計者，莫如脩行義而習文學。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 19,\n      \"canonicalText\": \"行義脩則見信，見信則受事；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 20,\n      \"canonicalText\": \"文學習則為明師，為明師則顯榮；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 21,\n      \"canonicalText\": \"此匹夫之美也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 22,\n      \"canonicalText\": \"然則無功而受事，無爵而顯榮，為有政如此，則國必亂，主必危矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 23,\n      \"canonicalText\": \"故不相容之事，不兩立也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 24,\n      \"canonicalText\": \"斬敵者受賞，而高慈惠之行；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 25,\n      \"canonicalText\": \"拔城者受爵祿，而信廉愛之說；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 26,\n      \"canonicalText\": \"堅甲厲兵以備難，而美薦紳之飾；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-27\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 27,\n      \"canonicalText\": \"富國以農，距敵恃卒，而貴文學之士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-28\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 28,\n      \"canonicalText\": \"廢敬上畏法之民，而養遊俠私劍之屬。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-29\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 29,\n      \"canonicalText\": \"舉行如此，治強不可得也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-30\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 30,\n      \"canonicalText\": \"國平養儒俠，難至用介士，所利非所用，所用非所利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-8_s-31\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-8\",\n      \"order\": 31,\n      \"canonicalText\": \"是故服事者簡其業，而遊學者日眾，是世之所以亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"且世之所謂賢者，貞信之行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"所謂智者，微妙之言也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"微妙之言，上智之所難知也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"今為眾人法，而以上智之所難知，則民無從識之矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 5,\n      \"canonicalText\": \"故糟糠不飽者不務梁肉，短褐不完者不待文繡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 6,\n      \"canonicalText\": \"夫治世之事，急者不得，則緩者非所務也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 7,\n      \"canonicalText\": \"今所治之政，民閒之事，夫婦所明知者不用，而慕上知之論，則其於治反矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 8,\n      \"canonicalText\": \"故微妙之言，非民務也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 9,\n      \"canonicalText\": \"若夫賢良貞信之行者，必將貴不欺之士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 10,\n      \"canonicalText\": \"不欺之士者，亦無不欺之術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 11,\n      \"canonicalText\": \"布衣相與交，無富厚以相利，無威勢以相懼也，故求不欺之士。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 12,\n      \"canonicalText\": \"今人主處制人之勢，有一國之厚，重賞嚴誅，得操其柄，以修明術之所燭，雖有田常、子罕之臣，不敢欺也，奚待於不欺之士？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 13,\n      \"canonicalText\": \"今貞信之士不盈於十，而境內之官以百數，必任貞信之士，則人不足官，人不足官則治者寡而亂者眾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-9_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-9\",\n      \"order\": 14,\n      \"canonicalText\": \"故明主之道，一法而不求智，固術而不慕信，故法不敗，而羣官無姦詐矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"今人主之於言也，說其辯而不求其當焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"其用於行也，美其聲而不責其功焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"是以天下之眾，其談言者務為辯而不周於用，故舉先王言仁義者盈廷，而政不免於亂；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"行身者競於為高而不合於功，故智士退處巖穴、歸祿不受，而兵不免於弱，政不免於亂，此其故何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"民之所譽，上之所禮，亂國之術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"今境內之民皆言治，藏商、管之法者家有之，而國愈貧，言耕者眾，執耒者寡也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"境內皆言兵，藏孫、吳之書者家有之，而兵愈弱，言戰者多，被甲者少也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"故明主用其力，不聽其言；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"賞其功，必禁無用；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"故民盡死力以從其上。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"夫耕之用力也勞，而民為之者，曰：可得以富也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 12,\n      \"canonicalText\": \"戰之為事也危，而民為之者，曰：可得以貴也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 13,\n      \"canonicalText\": \"今修文學、習言談，則無耕之勞、而有富之實，無戰之危、而有貴之尊，則人孰不為也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 14,\n      \"canonicalText\": \"是以百人事智而一人用力，事智者眾則法敗，用力者寡則國貧，此世之所以亂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 15,\n      \"canonicalText\": \"故明主之國，無書簡之文，以法為教；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 16,\n      \"canonicalText\": \"無先王之語，以吏為師；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 17,\n      \"canonicalText\": \"無私劍之捍，以斬首為勇。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 18,\n      \"canonicalText\": \"是境內之民，其言談者必軌於法，動作者歸之於功，為勇者盡之於軍。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 19,\n      \"canonicalText\": \"是故無事則國富，有事則兵強，此之謂王資。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-10_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-10\",\n      \"order\": 20,\n      \"canonicalText\": \"既畜王資而承敵國之舋，超五帝，侔三王者，必此法也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"今則不然，士民縱恣於內，言談者為勢於外，外內稱惡以待強敵，不亦殆乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"故群臣之言外事者，非有分於從衡之黨，則有仇讎之忠，而借力於國也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"從者，合眾弱以攻一強也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"而衡者，事一強以攻眾弱也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"皆非所以持國也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"今人臣之言衡者皆曰：「不事大則遇敵受禍矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"」事大未必有實，則舉圖而委，效璽而請兵矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"獻圖則地削，效璽則名卑，地削則國削，名卑則政亂矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"事大為衡未見其利也，而亡地亂政矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"人臣之言從者皆曰：「不救小而伐大則失天下，失天下則國危，國危而主卑。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"」救小未必有實，則起兵而敵大矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-12\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"救小未必能存，而交大未必不有疏，有疏則為強國制矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-13\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 13,\n      \"canonicalText\": \"出兵則軍敗，退守則城拔，救小為從未見其利，而亡地敗軍矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-14\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 14,\n      \"canonicalText\": \"是故事強則以外權士官於內，救小則以內重求利於外，國利未立，封土厚祿至矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-15\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 15,\n      \"canonicalText\": \"主上雖卑，人臣尊矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-16\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 16,\n      \"canonicalText\": \"國地雖削，私家富矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-17\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 17,\n      \"canonicalText\": \"事成則以權長重，事敗則以富退處。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-18\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 18,\n      \"canonicalText\": \"人主之於其聽說也，於其臣，事未成則爵祿已尊矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-19\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 19,\n      \"canonicalText\": \"事敗而弗誅，則遊說之士，孰不為用矰繳之說而徼倖其後？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-20\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 20,\n      \"canonicalText\": \"故破國亡主以聽言談者之浮說，此其故何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-21\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 21,\n      \"canonicalText\": \"是人君不明乎公私之利，不察當否之言，而誅罰不必其後也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-22\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 22,\n      \"canonicalText\": \"皆曰「外事大可以王，小可以安。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-23\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 23,\n      \"canonicalText\": \"」夫王者，能攻人者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-24\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 24,\n      \"canonicalText\": \"而安，則不可攻也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-25\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 25,\n      \"canonicalText\": \"強，則能攻人者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-26\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 26,\n      \"canonicalText\": \"治，則不可攻也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-27\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 27,\n      \"canonicalText\": \"治強不可責於外，內政之有也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-28\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 28,\n      \"canonicalText\": \"今不行法術於內，而事智於外，則不至於治強矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-29\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 29,\n      \"canonicalText\": \"鄙諺曰：「長袖善舞，多錢善賈。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-30\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 30,\n      \"canonicalText\": \"」此言多資之易為工也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-31\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 31,\n      \"canonicalText\": \"故治強易為謀，弱亂難為計。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-32\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 32,\n      \"canonicalText\": \"故用於秦者十變而謀希失，用於燕者一變而計希得，非用於秦者必智，用於燕者必愚也，蓋治亂之資異也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-33\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 33,\n      \"canonicalText\": \"故周去秦為從，期年而舉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-34\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 34,\n      \"canonicalText\": \"衛離魏為衡，半歲而亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-35\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 35,\n      \"canonicalText\": \"是周滅於從，衛亡於衡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-36\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 36,\n      \"canonicalText\": \"使周、衛緩其從衡之計，而嚴其境內之治，明其法禁，必其賞罰，盡其地力以多其積，致其民死以堅其城守，天下得其地則其利少，攻其國則其傷大，萬乘之國、莫敢自頓於堅城之下，而使強敵裁其弊也，此必不亡之術也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-37\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 37,\n      \"canonicalText\": \"舍必不亡之術而道必滅之事，治國者之過也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-11_s-38\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-11\",\n      \"order\": 38,\n      \"canonicalText\": \"智困於內而政亂於外，則亡不可振也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"民之故計，皆就安利如闢危窮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"今為之攻戰，進則死於敵，退則死於誅則危矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"棄私家之事而必汗馬之勞，家困而上弗論則窮矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"窮危之所在也，民安得勿避。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"故事私門而完解舍，解舍完則遠戰，遠戰則安。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"行貨賂而襲當塗者則求得，求得則私安，私安則利之所在，安得勿就？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"是以公民少而私人眾矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-8\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"夫明王治國之政，使其商工遊食之民少而名卑，以寡趣本務而趨末作。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-9\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"今世近習之請行則官爵可買，官爵可買則商工不卑也矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-10\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"姦財貨賈得用於市則商人不少矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-12_s-11\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"聚斂倍農而致尊過耕戰之士，則耿介之士寡而高價之民多矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13_s-1\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"是故亂國之俗，其學者則稱先王之道，以籍仁義，盛容服而飾辯說，以疑當世之法而貳人主之心。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13_s-2\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"其言古者，為設詐稱，借於外力，以成其私而遺社稷之利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13_s-3\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"其帶劍者，聚徒屬，立節操，以顯其名而犯五官之禁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13_s-4\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"其患御者，積於私門，盡貨賂而用重人之謁，退汗馬之勞。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13_s-5\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"其商工之民，修治苦窳之器，聚弗靡之財，蓄積待時而侔農夫之利。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13_s-6\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"此五者，邦之蠹也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"han-fei-zi_ch-49_p-13_s-7\",\n      \"workId\": \"han-fei-zi\",\n      \"chapterId\": \"han-fei-zi_ch-49\",\n      \"passageId\": \"han-fei-zi_ch-49_p-13\",\n      \"order\": 7,\n      \"canonicalText\": \"人主不除此五蠹之民，不養耿介之士，則海內雖有破亡之國，削滅之朝，亦勿怪矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
